type Entidade = "utilizador" | "encomenda";
type Acao = "criado" | "apagado" | "atualizado";

type NomeDeEvento = `${Entidade}:${Acao}`;          // 2 x 3 = 6 membros
type ConstanteDeEvento = Uppercase<`${Entidade}_${Acao}`>;

function emitir(evento: NomeDeEvento): string {
  return `emitido ${evento}`;
}

console.log(emitir("utilizador:criado"));    // emitido utilizador:criado
console.log(emitir("encomenda:atualizado")); // emitido encomenda:atualizado

// @ts-expect-error "enviado" não pertence a Acao
emitir("encomenda:enviado");

// @ts-expect-error o separador tem de ser dois pontos, como no tipo
emitir("utilizador-criado");

const constante: ConstanteDeEvento = "UTILIZADOR_APAGADO";
console.log(constante);                      // UTILIZADOR_APAGADO

type Formulario = {
  email: string;
  idade: number;
  aceitaTermos: boolean;
};

type Handlers<T> = {
  [K in keyof T as `on${Capitalize<K & string>}Mudou`]: (valor: T[K]) => void;
};

// Handlers<Formulario> é
// { onEmailMudou: (valor: string) => void;
//   onIdadeMudou: (valor: number) => void;
//   onAceitaTermosMudou: (valor: boolean) => void }

const handlers: Handlers<Formulario> = {
  onEmailMudou: (valor) => console.log("email:", valor.toLowerCase()),
  onIdadeMudou: (valor) => console.log("idade:", valor * 2),
  onAceitaTermosMudou: (valor) => console.log("termos:", valor ? "sim" : "nao"),
};

handlers.onEmailMudou("ANA@EXEMPLO.PT"); // email: ana@exemplo.pt
handlers.onIdadeMudou(21);               // idade: 42
handlers.onAceitaTermosMudou(true);      // termos: sim

// @ts-expect-error a chave gerada é onEmailMudou, não onEmail
const inexistente = handlers.onEmail;
console.log(inexistente);              // undefined

type EstadoDefinicoes = {
  tema: "claro" | "escuro";
  idioma: string;
  notificacoes: boolean;
};

type Definidores<T> = {
  [K in keyof T as `definir${Capitalize<K & string>}`]: (valor: T[K]) => void;
} & {
  [K in keyof T as `repor${Capitalize<K & string>}`]: () => void;
};

function criarDefinidores<T extends object>(estado: T): Definidores<T> {
  const inicial = { ...estado };
  const tabela: { [nome: string]: (valor?: unknown) => void } = {};

  for (const chave of Object.keys(estado) as (keyof T & string)[]) {
    const sufixo = `${chave.charAt(0).toUpperCase()}${chave.slice(1)}`;
    tabela[`definir${sufixo}`] = (valor) => {
      estado[chave] = valor as T[keyof T & string];
    };
    tabela[`repor${sufixo}`] = () => {
      estado[chave] = inicial[chave];
    };
  }

  return tabela as unknown as Definidores<T>;
}

const definicoes: EstadoDefinicoes = {
  tema: "claro",
  idioma: "pt-PT",
  notificacoes: true,
};

const api = criarDefinidores(definicoes);
api.definirTema("escuro");
api.definirIdioma("en-GB");
console.log(definicoes.tema, definicoes.idioma); // escuro en-GB

api.reporTema();
console.log(definicoes.tema);                    // claro

// @ts-expect-error definirTema só aceita "claro" ou "escuro"
api.definirTema("azul");

// @ts-expect-error reporIdioma não recebe argumentos
api.reporIdioma("pt-PT");
